(async () => {
  const tool = { name: "give_item", description: "Give the player an item from the world. Use when the NPC hands something over.",
    parameters: { type: "object", properties: { item: { type: "string", description: "the item name" }, count: { type: "integer", minimum: 1, maximum: 5 } }, required: ["item", "count"], additionalProperties: false } };
  const run = (id, messages) => new Promise((resolve) => {
    const deltas = [];
    const t0 = Date.now();
    const off = window.seed.inference.onEvent((e) => {
      if (e.id !== id) return;
      if (e.type === "delta") deltas.push(e.text);
      else { off(); resolve({ ms: Date.now() - t0, type: e.type, deltas: deltas.length, text: e.text, toolCalls: e.toolCalls, usage: e.usage, error: e.error }); }
    });
    window.seed.inference.chat({ id, messages, maxTokens: 300, temperature: 0.5, grammar: null, stop: [], tools: [tool], usage: { purpose: "resolve", scope: null } });
  });
  const base = [
    { role: "system", content: "You are Mara, a baker in a quiet village. Use tools only when the world must change." },
    { role: "user", content: "The player chose: Buy two loaves of bread. Intended effect: the player receives 2 bread. Enact it with tools only if the world must change; then answer with one in-world line in English." },
  ];
  const first = await run("e2e-apple-tool-1", base);
  if (first.type !== "done" || first.toolCalls.length === 0) return { first };
  const messages = [...base, { role: "assistant", content: first.text, toolCalls: first.toolCalls },
    ...first.toolCalls.map((c) => ({ role: "tool", content: JSON.stringify({ ok: true, gave: "2 bread" }), toolCallId: c.id, name: c.name }))];
  const second = await run("e2e-apple-tool-2", messages);
  return { first, second };
})()

(async () => {
